/**
 * "In this world, everyone has a number above their head" – timeline.
 * VOICE clock: every shot, number change and story event is anchored to a
 * word of the narration (script.vo.json, generated by scripts/voice/vo.py).
 */
import vo from "./script.vo.json";

export const FPS = 30;
export type Word = { w: string; start: number; end: number };
export type Line = { id: string; text: string; start: number; end: number; words: Word[] };
export const LINES = vo.lines as Line[];
export const DUR = Math.ceil((vo.dur + 2.2) * FPS) / FPS; // tail holds the final choice
export const FRAMES = Math.round(DUR * FPS);

const line = (id: string) => {
  const l = LINES.find((x) => x.id === id);
  if (!l) throw new Error(`no line ${id}`);
  return l;
};
/** start of line `id`, or of its word containing `match` */
export const at = (id: string, match?: string) => {
  const l = line(id);
  if (!match) return l.start;
  const w = l.words.find((x) => x.w.toLowerCase().replace(/[^\w,]/g, "").startsWith(match.toLowerCase()));
  if (!w) throw new Error(`no word ${match} in ${id}`);
  return w.start;
};
export const endOf = (id: string) => line(id).end;

// ---------------------------------------------------------------- story events
export const EV = {
  push: at("fly") - 0.15, // Vex shoves right before "I fly…"
  getUp: at("getup"), // Cubi starts to rise
  hit1: at("again1", "hits"),
  up1: at("again1", "i") + 0.6,
  hit2: at("again2"),
  silent: at("silent"),
  reveal: at("backup"), // hero moment: "It's how many times you got back up"
  flash: at("flash"),
  choices: at("flash", "two"),
  countdown: at("decide"),
};

/** Cubi's number over time (pure function of t). */
export const heroNumber = (t: number) => {
  if (t < at("two")) return 1;
  if (t < at("again1", "10")) return 2;
  if (t < at("again2", "100")) return 10;
  if (t < EV.reveal) return 100;
  const c0 = EV.reveal;
  const c1 = at("climb"); // "9,998" lands with the word
  if (t < c1) {
    const x = (t - c0) / (c1 - c0);
    return Math.round(100 + (9998 - 100) * x * x * x); // accelerating roll
  }
  if (t < at("climb", "9,999")) return 9998;
  return 9999;
};

// ---------------------------------------------------------------- shots
export type V3 = [number, number, number];
export type Shot = {
  id: string;
  from: number;
  set: "street" | "arena";
  p0: V3; // camera position at shot start
  p1: V3; // … at shot end (push-ins, drifts)
  t0: V3; // look-at target at start
  t1?: V3; // … at end (defaults to t0)
  fov?: number;
  shake?: number; // px amplitude at shot start, decays
  why: string;
};

const A: V3 = [0, 0, -120]; // arena origin
const a = (x: number, y: number, z: number): V3 => [A[0] + x, A[1] + y, A[2] + z];

const S = (id: string, from: number, set: Shot["set"], p0: V3, p1: V3, t0: V3, t1: V3 | undefined, why: string, extra: Partial<Shot> = {}): Shot => ({
  id,
  from,
  set,
  p0,
  p1,
  t0,
  t1,
  why,
  ...extra,
});

