export const shotAt = (t: number) => {
  let i = 0;
  while (i < SHOTS.length - 1 && t >= SHOTS[i + 1].from) i++;
  const s = SHOTS[i];
  const end = i < SHOTS.length - 1 ? SHOTS[i + 1].from : DUR;
  return { shot: s, index: i, k: Math.min(1, Math.max(0, (t - s.from) / (end - s.from))), end };
};

export const ARENA = A;
